head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.procJob = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.pJobTitl = js_jobtitl; // 권한
scwin.vBzProcsNo;
scwin.vIsuCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 재마감 처리 관리자만 보일 수 있도록
        if (js_dep_cd === 'ZSYS') {
            btn_Recls.setBackgroundImage("../img/btn_ReCls.gif");
            btn_Recls.setDisabled(false);
            btn_Recls.show("");
        } else {
            btn_Recls.hide();
        }

        // 담당자, 팀장확인 버튼
        btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
        btn_Revw.setDisabled(true);
        btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
        btn_Cls.setDisabled(true);

        // 마감일
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_TASK_DD.setValue(vCurDate);
        MaxTab_01.setSelectedTabIndex(1);
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === "1") {
            edt_TASK_DD.setReadOnly(true);
            img_TASK_DD.setDisabled(true);
            edt_TASK_DD.ReadOnlyBackColor = "#b9d4f7";
            edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
        } else if (nIndex === "2") {
            edt_TASK_DD.setReadOnly(false);
            img_TASK_DD.setDisabled(false);
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.MaxTab_01_OnSelChanged" });
    }
};

