///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const urltaskdd = "&TASK_DD=" + edt_TASK_DD.getValue();
    let url;

    // 상장일자 가져오기 (TBLD_BZ_CALND 테이블사용)
    url += urltaskdd;
    const sbmOptions = {
        id : "sbm_dts_Get_ListDD",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_Get_ListDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 마감이력가져오기 - etn으로 수정해야함
    url += urltaskdd;
    const sbmOptions2 = {
        id : "sbm_dts_Item",
        action : "/etn/EtnNewList.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 손실제한ETN 신규상장 내역
        url_new += "&SCREN_ID=" + "ULDSTF08200.xml";
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_New_Proc",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_New_Proc=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 상환주기 내역
        url_add += "&SCREN_ID=" + "ULDSTF08200.xml";
        url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions2 = {
            id : "sbm_dts_Add_Proc",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_Add_Proc=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 손실제한ETN 신규상장 마감처리내역
        url_new += "&SCREN_ID=" + "ULDSTF08200.xml";
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_New_Search",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_New_Search=body.content",
