/**
 * @method
 * @name revw
 * @description 담당자 확인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    scwin.procJob = "담당자 확인";
    if (!await scwin.checkProcDt(scwin.procJob)) return;
    res = window.confirm("담당자 확인 하시겠습니까?");
    if (res) {
        await scwin.trsRevw();
    }
};

/**
 * @method
 * @name cls
 * @description 팀장승인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cls = async function() {
    if (txb_APPROV_TM.getValue() === "") {
        await $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return true;
    }
    scwin.procJob = "마감처리";
    // if (! fn_checkProcDt(procJob))  return;
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }
    const commit = window.confirm("마감처리 하시겠습니까?");
    if (commit) {
        await scwin.trs();
    }
};

/**
 * @method
 * @name buttonSetDis
 * @description 담당자 승인, 팀장승인, 재마감처리
 * @returns {void}
 * @hidden N
 */
scwin.buttonSetDis = function() {
    // 담당자일때
    if (scwin.pJobTitl === "03") {
        if (txb_BZ_CLS_TM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else {
            if (txb_APPROV_EMP_NM.getValue() === "") {
                // 담당자확인을 않했을 경우
                btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
                btn_Revw.setDisabled(false);
            } else {
                btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
                btn_Revw.setDisabled(true);
            }
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        }
        //    showObj(btn_Recls, false);

    }
    // 팀장일때 - 마감처리
    else {
        if (txb_BZ_CLS_TM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_Cls.setDisabled(true);
        } else {
            if (txb_APPROV_EMP_NM.getValue() === "") {
                // 담당자확인을 않했을 경우
                btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
                btn_Revw.setDisabled(false);
                btn_Cls.setBackgroundImage("../img/btn_BosApv_d.gif");
                btn_Cls.setDisabled(true);
            } else {
                btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
                btn_Revw.setDisabled(true);
                btn_Cls.setBackgroundImage("../img/btn_BosApv.gif");
                btn_Cls.setDisabled(false);
            }
        }
        //    showObj(btn_Recls, false);

    }

    // 재마감 처리 버튼 - 시스템 관리자
    if (js_dep_cd === 'ZSYS') {
        btn_Recls.setBackgroundImage("../img/btn_ReCls.gif");
        btn_Recls.setDisabled(false);
        btn_Recls.show("");
    } else {
        btn_Recls.hide();
    }
};

/**
 * @method
 * @name checkProcDt
 * @description check Proc Dt 처리
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkProcDt = async function(str) {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    let pCheck = true;
    if (edt_TASK_DD.getValue() !== vCurDate) {
        await $c.win.alert("[마감일]이 현재일경우만 '" + str + "'를 할수 있습니다.");
        pCheck = false;
    }
    if (pCheck) {
        for (let i = 1; i <= dts_New_Proc.getRowCount(); i++) {
            if (dts_New_Proc.getCellData(i, "ISU_MKTPARTC_NO") === "") {
                await $c.win.alert("발행회사명에 대한 시장참가자번호가 없는 종목이 있습니다. 시스템관리자에게 문의바랍니다.");
                pCheck = false;
                break;
            }

            // if ( dts_New_Proc.NameString(i,"ISU_SHRS") <= 0 )

            // {

            //    alert("LP보유량이 '0'인 종목이 있습니다. 확인하여주십시오.");

            //    pCheck = false;

            //    break;

            // }

        }
    }
    return pCheck;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_New_Proc, {fileName: "손실제한ETN 신규상장 마감처리목록", type: "8"});
        $c.data.downloadGridViewExcel(grd_Add_Proc, {fileName: "손실제한ETN 상환주기 마감처리목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_New_Search, {fileName: "손실제한ETN 신규상장 송신목록", type: "8"});
        $c.data.downloadGridViewExcel(grd_Add_Search, {fileName: "손실제한ETN 추가상장 송신목록", type: "8"});
    }
};
